import { esc,fmt,dayKey,dateLabel,options } from '../utils.js';
import { lastExercise } from './metrics.js';
import { button,empty,heading } from '../ui/helpers.js';
import { exerciseRows,libraryFilters,routinePickerRows } from './catalog.js';
import { healthReady } from '../health/bridge.js';
import { sessionExerciseIds,selectedExerciseId,nextExerciseId,routineDisplayName } from './session.js';
export const weekDays=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
export function trainingView(state,ui) {
  const tab=ui.trainTab||'session';
  const tabs=`<div class="section-tabs training-tabs" role="group" aria-label="Secciones de entrenamiento">${[['session','Entrenar'],['routines','Rutinas'],['library','Ejercicios'],['history','Historial']].map(([id,label])=>button('training-tab',label,`data-tab="${id}" aria-pressed="${tab===id}"`)).join('')}</div>`;
  let content='';
  if(tab==='routines')content=`<section class="panel"><div class="day-title"><h2>Mis rutinas</h2>${button('new-routine','Nueva rutina')}</div><div class="routine-grid">${state.routines.map(r=>`<article class="routine-card"><h3>${esc(r.name)}</h3><p>${r.exerciseIds.length} ejercicios · ${r.days.length?r.days.map(d=>weekDays[d]).join(', '):'Sin días fijos'}</p><p class="help">${r.exerciseIds.map(id=>esc(state.exercises.find(e=>e.id===id)?.name||'Ejercicio')).join(' · ')}</p><div class="toolbar">${button('start-workout','Empezar',`data-id="${esc(r.id)}"`,'primary')}${button('edit-routine','Editar',`data-id="${esc(r.id)}"`)}${button('delete-routine','Eliminar',`data-id="${esc(r.id)}"`)}</div></article>`).join('')||'<p class="help">Crea tu primera rutina o empieza una sesión libre.</p>'}</div></section>`;
  else if(tab==='history')content=`<section class="panel"><h2>Historial de entrenamientos</h2>${[...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)||b.startedAt-a.startedAt).slice(0,ui.historyLimit||20).map(s=>`<details class="history-entry" data-view-key="history-${esc(s.id)}"><summary>${esc(dateLabel(s.date))} · ${esc(s.name)} <span>${s.sets.length} series · ${s.sets.filter(x=>x.records?.length).length} series con récord</span></summary>${s.notes?`<p class="note">${esc(s.notes)}</p>`:''}<ul>${s.sets.map(set=>`<li><strong>${esc(state.exercises.find(e=>e.id===set.exerciseId)?.name)}</strong> · ${fmt(set.weight,1)} kg × ${set.reps}${set.rpe!==null?' · RPE '+fmt(set.rpe,1):''}${set.records?.length?' · 🏅 '+set.records.map(esc).join(', '):''}</li>`).join('')}</ul><div class="toolbar">${healthReady()?button('health-export','Guardar en Salud',`data-id="${esc(s.id)}"`):''}${button('edit-notes','Editar notas',`data-id="${esc(s.id)}"`)}${button('delete-session','Eliminar sesión',`data-id="${esc(s.id)}"`)}</div></details>`).join('')||empty('Tu historial empieza aquí','Las sesiones terminadas aparecerán en esta sección.')}${state.sessions.length>(ui.historyLimit||20)?button('more-history','Mostrar más entrenamientos'):''}</section>`;
  else if(tab==='library')content=`<section class="panel exercise-library"><div class="day-title"><h2>Ejercicios</h2>${button('new-exercise','Añadir propio')}</div>${libraryFilters(state.exercises,ui.exerciseFilters)}<div id="library-results">${exerciseRows(state.exercises,ui.exerciseFilters)}</div></section>`;
  else content=state.draft?sessionView(state,ui):startView(state);

  return heading('','Entrenar','')+(state.draft&&tab==='session'?'':tabs)+content;
}
function startView(state) {
  return `<section class="panel easy-start"><h2>¿Qué vas a entrenar?</h2><p class="help">Toca una rutina para empezar.</p><div class="workout-choices">${state.routines.map(r=>`<button type="button" class="workout-choice" data-action="start-workout" data-id="${esc(r.id)}"><span><strong>${esc(routineDisplayName(r))}</strong><small>${r.exerciseIds.length} ejercicios · ${esc([...new Set(r.exerciseIds.map(id=>state.exercises.find(e=>e.id===id)?.group).filter(Boolean))].join(', '))}</small></span><span aria-hidden="true">→</span></button>`).join('')}<button type="button" class="workout-choice" data-action="start-workout" data-id="free"><span><strong>Entrenamiento libre</strong><small>Elige los ejercicios sobre la marcha.</small></span><span aria-hidden="true">+</span></button></div><details class="quiet-details"><summary>Registrar otro día</summary><form data-form="start-session"><label>Rutina<select name="routine">${options([['free','Entrenamiento libre'],...state.routines.map(r=>[r.id,routineDisplayName(r)])],'free')}</select></label><label>Fecha<input type="date" name="date" value="${dayKey()}" max="${dayKey()}" required></label><button class="secondary">Empezar con esta fecha</button></form></details></section>`;
}
function sessionView(state,ui) {
  const s=state.draft,ids=sessionExerciseIds(s),selected=selectedExerciseId(s,ui.exerciseId);
  const exercise=state.exercises.find(e=>e.id===selected),last=lastExercise(state.sessions,selected);
  const sets=s.sets.filter(x=>x.exerciseId===selected),recent=sets.at(-1)||last?.sets.at(-1),next=nextExerciseId(s,selected);
  const name=state.routines.find(r=>r.id===ui.routineId);
  const header=`<div class="easy-session-header"><div><p class="eyebrow">EN CURSO · ${esc(dateLabel(s.date))}</p><p>${esc(name?routineDisplayName(name):s.name)}</p></div><span class="pill">${s.sets.length} series guardadas</span></div>`;
  if(!exercise)return `<section class="panel active-session">${header}<div class="easy-empty"><h2>Elige tu primer ejercicio</h2><p class="help">Después solo tendrás que anotar el peso y las repeticiones.</p>${button('search-exercise','Elegir ejercicio','','primary')}</div><details class="quiet-details"><summary>Opciones de la sesión</summary>${button('discard-session','Descartar sesión')}</details></section>`;
  return `<section class="panel active-session">${header}<div class="easy-exercise"><p class="help">Ejercicio ${ids.indexOf(selected)+1} de ${ids.length}</p><h2>${esc(exercise.name)}</h2><p class="help">${esc(exercise.equipment)}</p>${button('search-exercise','Cambiar ejercicio')}</div>${last?`<p class="easy-last">La última vez: <strong>${fmt(last.sets.at(-1).weight,1)} kg × ${last.sets.at(-1).reps}</strong></p>`:''}<form data-form="set" data-exercise="${esc(selected)}"><p class="easy-series-label">Serie ${sets.length+1}</p><div class="set-fields"><label>Peso <span class="unit">kg</span><input type="number" name="weight" min="0" max="1000" step="0.1" inputmode="decimal" value="${recent?.weight??''}" placeholder="0" required></label><label>Repeticiones<input type="number" name="reps" min="1" max="100" step="1" inputmode="numeric" value="${recent?.reps??''}" placeholder="Ej. 10" required></label></div><button class="primary easy-save">Guardar serie</button><details class="quiet-details" data-view-key="effort"><summary>Ajustar descanso o esfuerzo</summary><div class="fields"><label>Descanso (segundos)<input type="number" name="rest" min="10" max="600" step="1" value="${ui.restSeconds||90}" required></label><label>Esfuerzo (opcional, de 1 a 10)<input type="number" name="rpe" min="1" max="10" step="0.5" inputmode="decimal" placeholder="10 = no podrías hacer otra"></label></div><p class="help">Sin carga externa registra 0 kg. En mancuernas usa siempre el mismo criterio de peso.</p></details></form><div class="easy-rest"><span>Descanso <strong id="rest-status" role="timer" aria-label="Tiempo de descanso">—</strong></span>${button('stop-rest','Saltar')}</div>${sets.length?`<div class="easy-saved" aria-label="Series de este ejercicio">${sets.map((set,i)=>`<button type="button" class="saved-series" data-action="edit-set" data-id="${esc(set.id)}" aria-label="Editar serie ${i+1}: ${fmt(set.weight,1)} kilos, ${set.reps} repeticiones"><span class="series-check" aria-hidden="true">✓</span><span>Serie ${i+1}</span><strong>${fmt(set.weight,1)} kg × ${set.reps}</strong><small>Editar</small></button>`).join('')}</div>`:''}<div class="easy-next">${next?button('next-exercise','Siguiente ejercicio','','secondary'):button('search-exercise','Elegir otro ejercicio')}</div><form data-form="finish-session" class="easy-finish"><button class="secondary" ${s.sets.length?'':'disabled'}>Terminar entrenamiento</button><details class="quiet-details" data-view-key="notes"><summary>Notas y más opciones</summary><label>Notas<textarea name="notes" maxlength="2000" placeholder="¿Cómo te has sentido?">${esc(ui.draftNotes?.id===s.id?ui.draftNotes.value:s.notes)}</textarea></label><div class="toolbar">${button('exercise-detail','Ver técnica',`data-id="${esc(selected)}"`)}${button('restart-rest','Reiniciar descanso')}${button('discard-session','Descartar sesión')}</div></details></form></section>`;
}
export function exerciseForm() {return `<form data-form="exercise"><h2>Nuevo ejercicio</h2><label>Nombre<input name="name" maxlength="100" required></label><label>Grupo muscular principal<input name="group" maxlength="60" required list="muscle-groups"></label><datalist id="muscle-groups">${['Pecho','Espalda','Hombros','Cuádriceps','Isquios','Glúteos','Bíceps','Tríceps','Gemelos','Core','Antebrazos','Aductores','Trapecio'].map(g=>`<option>${g}</option>`).join('')}</datalist><label>Equipo<input name="equipment" maxlength="100" required placeholder="Barra, mancuernas, polea…"></label><button class="primary">Guardar ejercicio</button></form>`;}
export function routineForm(state,routine) {return `<form data-form="routine" data-id="${esc(routine?.id||'')}"><h2>${routine?'Editar':'Crear'} rutina</h2><label>Nombre<input name="name" required maxlength="100" value="${esc(routine?.name||'')}" placeholder="Ej. Push"></label><h3>Días previstos</h3><div class="weekday-options">${weekDays.map((d,i)=>`<label class="check"><input type="checkbox" name="days" value="${i}" ${routine?.days.includes(i)?'checked':''}>${d}</label>`).join('')}</div><h3>Ejercicios</h3><p class="help">Elige hasta 50 ejercicios. Buscar no desmarca los que ya has elegido.</p><label>Buscar en la biblioteca<input type="search" id="routine-search" placeholder="Nombre, músculo o equipo…"></label><div class="exercise-picker">${routinePickerRows(state,routine)}</div><button class="primary">Guardar rutina</button></form>`;}

export function setEditForm(set) {
  return `<form data-form="edit-set" data-id="${esc(set.id)}"><h2>Editar serie</h2><div class="fields"><label>Peso total (kg)<input type="number" name="weight" min="0" max="1000" step="0.1" inputmode="decimal" value="${set.weight}" required></label><label>Repeticiones<input type="number" name="reps" min="1" max="100" step="1" inputmode="numeric" value="${set.reps}" required></label></div><label>RPE opcional<input type="number" name="rpe" min="1" max="10" step="0.5" inputmode="decimal" value="${set.rpe??''}"></label><div class="toolbar"><button class="primary">Guardar cambios</button>${button('delete-set','Eliminar serie',`data-id="${esc(set.id)}"`)}</div></form>`;
}
